{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Restorative Sound Baths</title>
  <meta name="description" content="Playful, premium sound bath experiences in {{CITY}}, {{STATE}}. Deep sensory work for busy people.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="split-diagonal">
  <header class="site-header">
    <div class="brand">
      <a href="/">{{BUSINESS_NAME}}</a>
      <small class="tag">{{TAGLINE}}</small>
    </div>
    <nav class="main-nav" aria-label="Primary navigation">
      <a href="/events.html">Upcoming</a>
      <a href="/private-sessions.html">1:1 & Groups</a>
      <a href="/pricing.html">Invest</a>
      <a href="/about.html">Our Story</a>
      <a href="/contact.html" class="cta">Get in Touch</a>
    </nav>
    <button class="menu-toggle" aria-expanded="false" aria-label="Open menu">☰</button>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero">
      <div class="hero-left">
        <h1>Immerse. Release. Reset.</h1>
        <p class="lead">A playful, premium sound bath intensive to recalibrate your nervous system — right here in {{CITY}}, {{STATE}}.</p>
        <p class="meta">Next event: <strong id="next-event">{{NEXT_EVENT_DATE}}</strong></p>
        <div class="hero-ctas">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/events.html">See full schedule</a>
        </div>
      </div>
      <div class="hero-right">
        <svg class="hero-pattern" viewBox="0 0 800 600" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
          <defs>
            <linearGradient id="g1" x1="0" x2="1">
              <stop offset="0%" stop-color="#fdf6ff"/>
              <stop offset="100%" stop-color="#eef9ff"/>
            </linearGradient>
            <pattern id="patt" patternUnits="userSpaceOnUse" width="200" height="200">
              <image href="assets/img/pattern.svg" x="0" y="0" width="200" height="200"/>
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#g1)"/>
          <rect width="100%" height="100%" fill="url(#patt)" opacity="0.25"/>
        </svg>
      </div>
    </section>

    <!-- DIAGNOSTIC (benefits + contraindications) -->
    <section id="diagnostic" class="cards">
      <h2>Who benefits — and when to check first</h2>
      <p class="intro">This intensive sound bath is for people seeking a deep sensory pivot: nervous system downshift, clearer sleep, and embodied presence.</p>
      <div class="card-grid">
        <article class="card">
          <h3>Immediate effects</h3>
          <ul>
            <li>Slow, restorative breath work paired with immersive tones.</li>
            <li>Reduced heart rate variability spikes and mental chatter.</li>
            <li>Heightened interoception — you feel rather than think.</li>
          </ul>
        </article>
        <article class="card">
          <h3>Who should be cautious</h3>
          <p class="muted">Contraindications: pregnancy (first trimester consult), epilepsy, active psychosis, recent head injury, or pacemakers — please check with a physician first.</p>
        </article>
        <article class="card">
          <h3>What to bring</h3>
          <ul>
            <li>Comfortable layers, a pillow, and a warm blanket.</li>
            <li>Yoga mat or soft pad. Eye mask optional.</li>
            <li>Water bottle and an open heart.</li>
          </ul>
        </article>
      </div>
    </section>

    <!-- PLAN (flow description) -->
    <section id="plan" class="plan">
      <h2>How the intensive unfolds</h2>
      <p class="lead">A carefully crafted arc of invitation, vibration, and integration — anchored in sensory richness.</p>
      <ol class="flow">
        <li>
          <strong>Arrival & Grounding (15 min)</strong>
          <p>We set intention, tune in with gentle breathwork, and settle into supportive props.</p>
        </li>
        <li>
          <strong>Layered Sound Journey (45–60 min)</strong>
          <p>Crystal bowls meet the deep wash of a gong, with chimes and tuning forks threading clarity. Expect big, immersive waves and quiet harmonic micro-moments.</p>
        </li>
        <li>
          <strong>Slow Emergence (10–15 min)</strong>
          <p>Soft monochord or bell strokes bring you gently back. We close with journaling prompts and a brief sharing circle for integration.</p>
        </li>
      </ol>
    </section>

    <!-- MICRO_HABITS (prep + aftercare) -->
    <section id="micro_habits" class="micro-habits">
      <h2>Tiny rituals that deepen the work</h2>
      <div class="habits">
        <div class="habit">
          <h4>Before: Hydrate & Slow Down</h4>
          <p>Skip heavy meals and alcohol for at least 3 hours. Drink water and arrive 10 minutes early to breathe.</p>
        </div>
        <div class="habit">
          <h4>During: Notice Sensations</h4>
          <p>Label sensations gently: warm, tingling, sinking. No need to narrate — naming helps the nervous system integrate.</p>
        </div>
        <div class="habit">
          <h4>After: Move Softly</h4>
          <p>Give yourself a half hour post-session for slow walking, tea, and journaling to anchor insights.</p>
        </div>
      </div>
    </section>

    <!-- PRICING (teaser + link) -->
    <section id="pricing" class="pricing">
      <h2>Invest in deep reset</h2>
      <p class="subtitle">Offer model: intensive. We curate small groups for high-impact shifts.</p>
      <div class="pricing-grid">
        <div class="price-box">
          <h3>Group Intensive</h3>
          <p class="amount">$35 — drop-in</p>
          <p class="desc">Upcoming events at {{VENUE_NAME}} with mixed instruments: crystal bowls, chimes, and a deep gong wash.</p>
          <a class="btn" href="/pricing.html">See details</a>
        </div>
        <div class="price-box">
          <h3>Private 1:1</h3>
          <p class="amount">$150 — 60 min</p>
          <p class="desc">Tailored session with monochord and tuning forks for somatic integration.</p>
          <a class="btn" href="/private-sessions.html">Book private</a>
        </div>
        <div class="price-box">
          <h3>Couples / Corporate</h3>
          <p class="amount">Custom pricing</p>
          <p class="desc">Immersive team or intimate partner sessions available upon request.</p>
          <a class="btn" href="/contact.html">Inquire</a>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="cta-bleed">
      <div class="bleed-inner">
        <h2>Ready to drop in?</h2>
        <p class="small">Reserve your spot with {{FACILITATOR_NAME}} at {{VENUE_NAME}} — space is intentionally limited.</p>
        <div class="cta-buttons">
          <a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn large ghost" href="/book.html">Request private session</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div>
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Facilitated by {{FACILITATOR_NAME}} in {{CITY}}, {{STATE}}.</p>
      <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> — Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
    </div>
    <nav class="foot-nav">
      <a href="/faq.html">FAQ</a>
      <a href="/about.html">About</a>
      <a href="/contact.html">Contact</a>
    </nav>
  </footer>

<script src="assets/js/main.js" defer></script>
</body>
</html>"} 
