{"path":"assets/css/styles.css","content":"/* Playful premium split-diagonal layout */
:root{
  --bg:#fbfbfe;
  --accent:#7b61ff;
  --muted:#6b6b7a;
  --glass:rgba(255,255,255,0.6);
  --maxw:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;background:linear-gradient(180deg,var(--bg),#f2fbff);color:#0b1020}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;max-width:var(--maxw);margin:0 auto}
.brand a{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.1rem}
.brand .tag{display:block;font-size:0.78rem;color:var(--muted)}
.main-nav a{margin:0 8px;color:#111;text-decoration:none}
.main-nav a.cta{background:var(--accent);color:white;padding:8px 12px;border-radius:8px}
.menu-toggle{display:none;background:none;border:0;font-size:1.3rem}
.split-diagonal main{max-width:var(--maxw);margin:20px auto;padding:24px}
.hero{display:grid;grid-template-columns:1fr 420px;gap:24px;align-items:center;padding:40px;border-radius:18px;background:linear-gradient(120deg,rgba(123,97,255,0.06),rgba(14,186,217,0.03));position:relative;overflow:hidden}
.hero-left h1{font-size:2.2rem;margin:0 0 8px}
.hero-left .lead{margin:0 0 12px;color:var(--muted)}
.hero-left .meta{font-size:0.9rem;color:#333}
.hero-ctas .btn{display:inline-block;margin-right:10px}
.btn{background:white;border:1px solid rgba(11,16,32,0.06);padding:10px 14px;border-radius:12px;text-decoration:none;color:#071028}
.btn.primary{background:var(--accent);color:white;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(11,16,32,0.06)}
.hero-right{display:flex;align-items:center;justify-content:center}
.hero-pattern{width:100%;height:100%;max-height:340px}

.cards{padding:36px 18px;margin-top:18px}
.cards h2{margin:0 0 6px}
.card-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:16px}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.8),var(--glass));padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(17,16,40,0.06)}
.card h3{margin-top:0}
.card .muted{color:var(--muted)}

.plan{padding:34px 18px}
.flow{list-style:none;padding:0;margin:12px 0 0}
.flow li{padding:14px;border-left:3px solid var(--accent);margin-bottom:12px;background:#fff;border-radius:8px}

.micro-habits{padding:34px 18px;background:linear-gradient(90deg,rgba(123,97,255,0.03),transparent)}
.habits{display:flex;gap:12px}
.habit{background:white;padding:12px;border-radius:10px;flex:1}
.habit h4{margin-top:0}

.pricing{padding:34px 18px}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.price-box{padding:16px;border-radius:12px;background:linear-gradient(180deg,#ffffff,#fbfbff);box-shadow:0 4px 18px rgba(11,16,32,0.04)}
.price-box .amount{font-weight:700;color:var(--accent);margin:6px 0}

.cta-bleed{margin-top:30px;padding:28px;border-radius:14px;background:linear-gradient(120deg,#fff7ff,#f0feff);text-align:center}
.bleed-inner{max-width:820px;margin:0 auto}
.btn.large{padding:14px 22px;border-radius:14px}

.site-footer{max-width:var(--maxw);margin:30px auto;padding:18px;color:var(--muted);display:flex;justify-content:space-between;align-items:center}
.foot-nav a{margin-left:8px;color:var(--muted);text-decoration:none}

/* Responsive */
@media(max-width:900px){
  .hero{grid-template-columns:1fr;}
  .card-grid{grid-template-columns:1fr}
  .pricing-grid{grid-template-columns:1fr}
  .habits{flex-direction:column}
  .main-nav{display:none}
  .menu-toggle{display:block}
}

/* Diagonal accent */
.split-diagonal::before{content:"";position:fixed;left:-20vw;top:60vh;width:140vw;height:60vh;background:linear-gradient(120deg,rgba(123,97,255,0.06),rgba(14,186,217,0.03));transform:rotate(-12deg);z-index:-1}

/* subtle focus */
a:focus{outline:3px solid rgba(123,97,255,0.18);outline-offset:2px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Small interactive helpers for the template
  document.addEventListener('DOMContentLoaded',function(){
    var yearEl = document.getElementById('year');
    if(yearEl) yearEl.textContent = new Date().getFullYear();

    var menu = document.querySelector('.menu-toggle');
    var nav = document.querySelector('.main-nav');
    if(menu && nav){
      menu.addEventListener('click',function(){
        var open = this.getAttribute('aria-expanded') === 'true';
        this.setAttribute('aria-expanded', String(!open));
        nav.style.display = open ? '' : 'flex';
      });
    }

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click',function(e){
        e.preventDefault();
        var id = this.getAttribute('href').slice(1);
        var el = document.getElementById(id);
        if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
      });
    });

    // Generate a small calendar teaser on events link hover (progressive enhancement)
    var nextEvent = document.getElementById('next-event');
    if(nextEvent){
      nextEvent.addEventListener('click', function(){
        // If CMS replaces {{NEXT_EVENT_DATE}} this will be real; otherwise show a friendly prompt
        if(nextEvent.textContent.indexOf('{{') !== -1){
          alert('Visit the Upcoming page to see full schedule.');
        }
      });
    }
  });
})();
"} 
